BASE = """<!doctype html><html lang=zh-CN><head><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>{{ title }} · CampusToday</title><style>
:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#172033;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.wrap{max-width:980px;margin:auto;padding:24px}.nav{display:flex;gap:18px;align-items:center;background:#172033;color:white;padding:14px 24px}.nav a{color:white;text-decoration:none}.nav b{margin-right:auto}.card{background:white;border:1px solid #dfe6f0;border-radius:14px;padding:22px;margin:18px 0;box-shadow:0 4px 18px #1e293b0d}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px}.metric{background:#f7f9fc;padding:14px;border-radius:10px}.muted{color:#667085}.ok{color:#137333}.warn{color:#b54708}label{display:block;margin:12px 0 5px}input,select{width:100%;padding:10px;border:1px solid #c9d2df;border-radius:8px}button{background:#2257d7;color:white;border:0;border-radius:8px;padding:10px 16px;margin-top:16px;cursor:pointer}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #e6ebf2;font-size:14px}.flash{background:#fff4ce;padding:12px;border-radius:8px}</style></head><body>
{% if session.get('user') %}<nav class=nav><b>CampusToday</b><a href='/dashboard'>状态</a><a href='/history'>历史</a><a href='/settings'>设置</a><a href='/logs'>日志</a><form action='/logout' method=post><input type=hidden name=csrf value='{{ csrf_token() }}'><button style='margin:0;background:#475467'>退出</button></form></nav>{% endif %}<main class=wrap>{% with ms=get_flashed_messages() %}{% for m in ms %}<p class=flash>{{m}}</p>{% endfor %}{% endwith %}{{ content|safe }}</main></body></html>"""

LOGIN = """<div class=card style='max-width:420px;margin:10vh auto'><h1>CampusToday</h1><p class=muted>晚查寝自动化服务管理后台</p><form method=post><input type=hidden name=csrf value='{{ csrf_token() }}'><label>用户名</label><input name=username autocomplete=username required><label>密码</label><input type=password name=password autocomplete=current-password required><button>登录</button></form></div>"""

DASHBOARD = """<h1>今日状态</h1><div class=grid><div class=metric><div class=muted>调度器</div><b class={{ 'ok' if status.running else 'warn' }}>{{ '运行中' if status.running else '已停止' }}</b></div><div class=metric><div class=muted>自动运行</div><b>{{ 'ON' if status.enabled else 'OFF' }}</b></div><div class=metric><div class=muted>今日校园接口</div><b>{{ status.integration }}</b></div><div class=metric><div class=muted>位置验证</div><b>{{ location.reason if location else '尚无证明' }}</b></div></div><div class=card><h2>安全状态</h2><p>当前不会使用历史坐标或固定坐标提交。只有可信设备上传的新鲜位置证明、地理围栏校验通过并且当前协议明确启用时，才允许进入提交状态。</p><p class=muted>上次检查：{{status.last_check or '尚未运行'}}<br>下次检查：{{status.next_run or '未知'}}</p></div>"""

SETTINGS = """<h1>设置</h1><div class=card><form method=post><input type=hidden name=csrf value='{{ csrf_token() }}'><label>自动运行</label><select name=auto_enabled><option value=false {{'selected' if not status.enabled}}>OFF</option><option value=true {{'selected' if status.enabled}}>ON</option></select><label>监测开始</label><input type=time name=monitor_start value='{{values.monitor_start}}' required><label>监测结束</label><input type=time name=monitor_end value='{{values.monitor_end}}' required><button>保存</button></form></div><div class=card><h2>受保护配置</h2><p class=muted>今日校园账号、接口入口、校园围栏和可信设备令牌只能通过服务器端 <code>.env</code> 配置，避免浏览器页面泄露敏感信息。</p></div>"""

TABLE = """<h1>{{heading}}</h1><div class=card><table><thead><tr>{% for h in headers %}<th>{{h}}</th>{% endfor %}</tr></thead><tbody>{% for row in rows %}<tr>{% for cell in row %}<td>{{cell}}</td>{% endfor %}</tr>{% else %}<tr><td colspan={{headers|length}} class=muted>暂无记录</td></tr>{% endfor %}</tbody></table></div>"""

